questionvariables.text:
/* Randomly select one of four possible angles */
q: 1+rand(4);

/* Select the coefficient of pi */
m: if q=1 then 1
   elseif q=2 then 2
   elseif q=3 then 4
   else 5;

/* Generate the negative angle */
theta: -m*%pi/6;

/* Determine the reference angle coefficient */
r: if m<=2 then m
   else 6-m;

/* Reference angle */
alpha: r*%pi/6;

/* Calculate the absolute values of the ratios */
sin_mag: if r=1 then 1/2
         else sqrt(3)/2;

cos_mag: if r=1 then sqrt(3)/2
         else 1/2;

tan_mag: if r=1 then sqrt(3)/3
         else sqrt(3);

/* Determine the signs using the quadrant */
ta1: -sin_mag;

ta2: if m<=2 then cos_mag
     else -cos_mag;

ta3: if m<=2 then -tan_mag
     else tan_mag;

/* Teacher answers */
ta_sin: ta1;
ta_cos: ta2;
ta_tan: ta3;
